package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import com.microsoft.playwright.options.FilePayload;
import java.nio.file.Path;
import java.util.*;

final class FieldVisitsBrowserAcceptance {
 static void run(BrowserTest h)throws Exception {
  String parent,task,technician,group,ci;
  try(var db=h.store.open()){
   String admin=PlatformFoundationTest.bind(db);Service.createAccount(db,map("name","VisitBrowserTechnician","role","agent","password",WorkflowSupport.PASSWORD));technician=RecordAccess.owner(db,"VisitBrowserTechnician");group=Service.create(db,"sys_user_group",map("short_description","Visit service team"),"admin").get("sys_id").toString();db.update("INSERT INTO os_group_member(group_id,user_id) VALUES(?,?)",group,technician);parent=Service.create(db,"incident",map("short_description","Repair and verify the reception terminal"),"admin").get("sys_id").toString();WorkTasks.command(db,"incident",parent,map("operation","configure","revision",0,"record_revision",0,"close_at","6"));task=objects(WorkTasks.command(db,"incident",parent,map("operation","create","revision",1,"record_revision",1,"summary","Visit reception <script>","details","Inspect, repair and verify the terminal","group_id",group,"required",true,"predecessors",List.of())).get("tasks")).getFirst().get("task_id").toString();ci=Service.create(db,"cmdb_ci",map("short_description","Visit replacement adapter"),"admin").get("sys_id").toString();ServiceClocks.calendar(db,admin,map("name","VisitBrowserDay","calendar",map("zone","UTC","start","08:00","end","18:00","days",List.of(1,2,3,4,5),"holidays",List.of())));FieldAvailability.save(db,map("username","VisitBrowserTechnician","calendar_id","VisitBrowserDay","active",true,"revision",0));db.connection.commit();
  }
  try(var p=Playwright.create();var browser=p.chromium().launch();var adminContext=browser.newContext();var workerContext=browser.newContext()){
   var page=adminContext.newPage();h.login(page,"admin");page.navigate(h.base()+"/record/incident/"+parent+"/work-tasks");page.locator("#task-"+task).getByRole(AriaRole.LINK,new Locator.GetByRoleOptions().setName("Field visit report")).press("Enter");page.getByLabel("Required checks, one per line").fill("Inspect installation <script>\nVerify the customer result");page.getByLabel("Evidence requirement").selectOption("true");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/field-visit-plan-light.png")).setFullPage(true));page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save visit plan")).press("Enter");assertThat(page.locator("main ol li")).hasCount(2);assertThat(page.getByLabel("Required checks, one per line")).hasValue("Inspect installation <script>\nVerify the customer result");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Back to dispatch")).press("Enter");page.getByLabel("Technician",new Page.GetByLabelOptions().setExact(true)).selectOption(technician);page.getByLabel("Visit location").fill("Reception desk");page.getByLabel("Visit start (UTC)").fill("2030-01-07T09:00:00Z");page.getByLabel("Visit end (UTC)").fill("2030-01-07T10:00:00Z");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Assign field visit")).press("Enter");
   var worker=workerContext.newPage();h.login(worker,"VisitBrowserTechnician");worker.navigate(h.base()+"/record/incident/"+parent+"/field-dispatch/"+task);worker.getByLabel("Decision reason").fill("Ready for reception visit");worker.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Accept field visit")).press("Enter");worker.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Field visit report")).press("Enter");worker.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Start travel")).press("Enter");assertThat(worker.locator("main")).containsText("Travelling");worker.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Check in and start work")).press("Enter");worker.getByLabel("Find a configuration item").fill("Visit replacement");worker.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Search configuration items")).press("Enter");worker.getByLabel("Configuration item",new Page.GetByLabelOptions().setExact(true)).selectOption(ci);worker.getByLabel("Usage direction").selectOption("used");worker.getByLabel("Quantity",new Page.GetByLabelOptions().setExact(true)).fill("2");worker.getByLabel("Usage notes").fill("Replaced the adapter <script>alert(1)</script>");worker.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Record part usage")).press("Enter");assertFalse(worker.url().contains("?"));assertThat(worker.locator("main")).containsText("used · Quantity 2");ReleaseBrowserAcceptance.accessible(worker);worker.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/field-visit-onsite-light.png")).setFullPage(true));
   worker.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Case and evidence uploads")).press("Enter");worker.locator("input[type=file]").setInputFiles(new FilePayload("field-proof.txt","text/plain","Terminal output verified".getBytes()));worker.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Upload").setExact(true)).press("Enter");worker.navigate(h.base()+"/record/incident/"+parent+"/field-visit/"+task);worker.getByLabel("Inspect installation <script>",new Page.GetByLabelOptions().setExact(true)).check();worker.getByLabel("Verify the customer result",new Page.GetByLabelOptions().setExact(true)).check();worker.getByLabel("field-proof.txt",new Page.GetByLabelOptions().setExact(true)).check();worker.getByLabel("Part usage review").selectOption("true");worker.getByLabel("Completion notes").fill("Verified with reception\nTerminal works correctly <script>safe</script>");worker.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Complete field visit")).press("Enter");assertThat(worker.locator("main")).containsText("Complete");assertThat(worker.locator("main")).containsText("Inspect installation <script> · Confirmed");assertThat(worker.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Download matching evidence"))).hasCount(1);assertThat(worker.locator("main script")).hasCount(0);worker.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).press("Enter");worker.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(worker);assertEquals(false,worker.evaluate("document.documentElement.scrollWidth>window.innerWidth"));worker.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/field-visit-complete-dark.png")).setFullPage(true));
   page.navigate(h.base()+"/record/incident/"+parent+"/work-tasks");WorkTasksBrowserAcceptance.create(page,"Stranded follow-up visit",group,"");String stranded=WorkTasksBrowserAcceptance.id(h,"Stranded follow-up visit");page.locator("#task-"+stranded).getByRole(AriaRole.LINK,new Locator.GetByRoleOptions().setName("Field visit report")).press("Enter");page.getByLabel("Required checks, one per line").fill("Verify access to the site");page.getByLabel("Evidence requirement").selectOption("false");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save visit plan")).press("Enter");page.getByLabel("Administrator termination reason").fill("Site closed; arrange replacement work");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("End stranded visit as incomplete")).press("Enter");assertThat(page.locator("main")).containsText("Incomplete");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/field-visit-abort-light.png")).setFullPage(true));
  }
 }
}
